SELECT p.id AS position_id, pt.point, pt.at_ts, iv.code AS interval_code, s.id, s.candle_open_time, s.generated_at, TIMESTAMPDIFF(SECOND, s.generated_at, pt.at_ts) AS age_s, s.decision, s.original_decision, s.total_score, s.confidence_score, s.latest_price, s.data_quality_valid FROM paper_position p JOIN (SELECT id AS pid, 'OPEN' AS point, opened_at AS at_ts FROM paper_position WHERE id IN (182,172,162,158,143,137) UNION ALL SELECT id, 'CLOSE', closed_at FROM paper_position WHERE id IN (182,172,162,158,143,137)) pt ON pt.pid=p.id CROSS JOIN (SELECT '1m' AS code UNION ALL SELECT '5m' UNION ALL SELECT '1h') iv LEFT JOIN trade_signal s ON s.id = (SELECT s2.id FROM trade_signal s2 WHERE s2.symbol=p.symbol AND s2.interval_code=iv.code AND s2.generated_at <= pt.at_ts ORDER BY s2.generated_at DESC LIMIT 1) ORDER BY p.id, pt.point DESC, iv.code